def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('required_verb') or ''
    tt = nb.get('task_type') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal object; put it back or recover, then find the requested ' + target + '.'
    elif stage == 'take_target' and nb.get('target_type') and any(a.startswith('take ') and nb.get('target_type') in a for a in (ctx.get('admissible') or [])):
        msg = 'A requested ' + target + ' is available here. Take the target type instead of other objects.'
    elif stage == 'transform' and verb:
        place = 'sinkbasin'
        if verb == 'heat':
            place = 'microwave or stoveburner'
        if verb == 'cool':
            place = 'fridge'
        msg = 'Before placing, ' + verb + ' the ' + target + ' using the ' + place + '. Do not put the untransformed item at the destination.'
    elif stage == 'put_target' and dest:
        msg = 'You are at the requested ' + dest + '. Put the ' + target + ' there now; do not examine or take it back.'
    elif stage == 'go_destination' and dest:
        msg = 'Carry the ' + target + ' to the requested ' + dest + ' and put it there; avoid unrelated containers.'
    elif stage == 'find_target' and 'two' in str(tt) and nb.get('placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + '.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

