def hook(ctx, nb):
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(getv(ctx, 'task.task_type', ''))
    if not target:
        return None
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    adm = [text(a) for a in (ctx.get('admissible') or [])]
    inv = text(getv(ctx, 'world.inventory', ''))
    carrying = bool(target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and target not in inv and 'not carrying' not in inv and 'nothing' not in inv)
    if wrong and act.startswith('put ') and target not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested target type. Do not place a substitute; recover and find the requested ' + target + '.'}
    if verb and not nb.get('transform_done') and carrying and act.startswith('put ') and target in act and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First ' + verb + ' it, then carry it to the destination.'}
    if 'two' in str(getv(ctx, 'task.task_type', '')) and act.startswith('take ') and target in act and nb.get('placed_count', 0) > 0:
        locs = text(getv(ctx, 'world.placed_locations', []))
        if locs and locs in act:
            return {'kind': 'block_and_prompt', 'message': 'Do not take back a target already placed for the two-object task. Find another ' + target + ' and use the same destination.'}
    if not (verb and not nb.get('transform_done') and carrying and target in act and act.startswith(verb + ' ')):
        return None
    if not verb:
        return None
    trans_ready = False
    for a in adm:
        if a.startswith(verb + ' ') and target in a:
            trans_ready = True
    if trans_ready and not (act.startswith(verb + ' ') and target in act):
        return {'kind': 'block_and_prompt', 'message': 'The required ' + verb + ' action is available now. Use it on the ' + target + ' before placing or moving away.'}
    take_ready = bool(any(a.startswith('take ') and target in a for a in adm))
    if take_ready and not (act.startswith('take ') and target in act) and (getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)):
        return {'kind': 'block_and_prompt', 'message': 'A requested ' + target + ' is available here. Take the target type instead of continuing to search or inspect.'}
    return None
